SELECT 'contadores iguales al maximo historico por empresa y tipo (recien sembrados)' AS verificacion, IF((SELECT COUNT(*) FROM `u611730801_Plataforma`.canecas_secuencias s JOIN (SELECT e.id AS empresa_id, t.tipo, COALESCE(h.maximo,0) AS maximo FROM `u611730801_Plataforma`.empresas e CROSS JOIN (SELECT 'COMPRA' AS tipo UNION ALL SELECT 'PRODUCTO' UNION ALL SELECT 'VENTA') t LEFT JOIN (SELECT empresa_id, 'COMPRA' AS tipo, MAX(CAST(REGEXP_REPLACE(UPPER(TRIM(referencia)), '^COMP[ _-]?', '') AS UNSIGNED)) AS maximo FROM `u611730801_Plataforma`.canecas_compras WHERE UPPER(TRIM(referencia)) REGEXP '^COMP[ _-]?[0-9]{1,15}$' GROUP BY empresa_id UNION ALL SELECT empresa_id, 'VENTA', MAX(CAST(REGEXP_REPLACE(UPPER(TRIM(documento)), '^VTA[ _-]?', '') AS UNSIGNED)) FROM `u611730801_Plataforma`.canecas_ventas WHERE UPPER(TRIM(documento)) REGEXP '^VTA[ _-]?[0-9]{1,15}$' GROUP BY empresa_id UNION ALL SELECT empresa_id, 'PRODUCTO', MAX(CAST(REGEXP_REPLACE(UPPER(TRIM(codigo)), '^CAN[ _-]?', '') AS UNSIGNED)) FROM `u611730801_Plataforma`.canecas_productos WHERE UPPER(TRIM(codigo)) REGEXP '^CAN[ _-]?[0-9]{1,15}$' GROUP BY empresa_id) h ON h.empresa_id=e.id AND h.tipo=t.tipo) esperado ON esperado.empresa_id=s.empresa_id AND esperado.tipo=s.tipo WHERE s.ultimo=esperado.maximo)=(SELECT COUNT(*)*3 FROM `u611730801_Plataforma`.empresas) AND (SELECT COUNT(*) FROM `u611730801_Plataforma`.canecas_secuencias)=(SELECT COUNT(*)*3 FROM `u611730801_Plataforma`.empresas), 'OK', 'DETENER') AS resultado;
SELECT 'recuento canecas_ventas (debe coincidir con el preflight)' AS verificacion, CAST(COUNT(*) AS CHAR) AS resultado FROM `u611730801_Plataforma`.canecas_ventas;
SELECT 'recuento canecas_productos (debe coincidir con el preflight)' AS verificacion, CAST(COUNT(*) AS CHAR) AS resultado FROM `u611730801_Plataforma`.canecas_productos;
SELECT 'recuento canecas_compras' AS verificacion, CAST(COUNT(*) AS CHAR) AS resultado FROM `u611730801_Plataforma`.canecas_compras;
